void service_coverage(const CraftJobReadContext&x,const CraftJob&j,const CraftServiceSpan&s){
 if(!x.character_sources)throw Failure{common_failure("CraftCharacterSourceProviderRequired",j.id,ErrorKind::unsupported_capability).error};
 if(&x.character_sources->body.common!=&x.materials.common||&x.character_sources->jobs!=&x.materials.jobs||&x.character_sources->recipes!=&x.materials.recipes)fail("CraftCharacterSourceContextMismatch",j.id);
 take(validate_craft_participant_body_span(*x.character_sources,j,s.actual));
 if(!x.spatial_sources)throw Failure{common_failure("CraftSpatialSourceProviderRequired",j.id,ErrorKind::unsupported_capability).error};
 if(&x.spatial_sources->craft!=&x)fail("CraftSpatialSourceContextMismatch",j.id);
 take(validate_craft_participant_spatial_span(*x.spatial_sources,j,s.actual));
 take(x.original.validate_adopted_craft_service_interval(s.actual));
 for(const auto&ref:s.actual.participation_sources)if(!is_craft_participant_body_source(ref)&&!is_craft_participant_spatial_source(ref))take(x.original.validate_work_service_participation_source(s.actual,ref));
}
WorldMoment now(const CraftJobReadContext&x){auto m=take(x.clock.read_current_moment());take(compare_world_moments(m,m));if(m.half_day_tick<x.materials.common.tick())fail("CraftClockBeforeCommon");return m;}
// Full/hot admission only; original gate, holder and service reads stay source-local.
void participant_qualification(const CraftJobReadContext&x,const CraftTerms&t,const SourceRef*actual){
 if(!x.character_sources)throw Failure{common_failure("CraftCharacterSourceProviderRequired",t.job_id,ErrorKind::unsupported_capability).error};
 const auto&sources=*x.character_sources;
 if(&sources.body.common!=&x.materials.common||&sources.jobs!=&x.materials.jobs||&sources.recipes!=&x.materials.recipes||!same(sources.body.actual_now,now(x)))fail("CraftCharacterSourceContextMismatch",t.job_id);
 take(validate_craft_participant_qualification(sources,t,actual));
}
void context(CommonStore&c,CraftJobsState&s,ActionElapsedStore&e,const CraftJobWriteContext&x){if(!x.read.occupancy)fail("CraftOccupancyProviderRequired");if(&c!=&x.read.materials.common||&s!=&x.read.materials.jobs||&e!=&x.read.elapsed||!x.effects.bound_to(c,s)||s.schema_version!=1)fail("CraftCandidateContextMismatch");}
