Outcome<CraftJobsState> make_initial_craft_jobs(const CommonStore&common,const CommonCatalog&shared,
 const ItemServiceCatalog&items,const CraftRecipeCatalog&recipes,Integer selected_version){
 if(selected_version!=1)return {false,{},common_failure("UnsupportedCraftJobsVersion",{},ErrorKind::unsupported_capability).error};
 auto valid=validate_craft_recipe_catalog(recipes,shared,items);if(!valid.ok)return {false,{},valid.error};
 for(const auto&row:common.state().facts.rows())if(row.second.domain=="crafting")return {false,{},common_failure("InitialCraftOriginalSourcesRequired",row.first).error};
 for(const auto&row:common.state().actions.rows())if(row.second.kind=="craft_job")return {false,{},common_failure("InitialCraftOriginalExecutionRequired",row.first).error};
 return {true,CraftJobsState{}, {}};
}
ActionTimeRegistration craft_action_time_registration(){return {"craft_job","crafting","craft_work_gate",1,1,ActionTimeMode::shared_work,ActionRemainingMeaning::service_estimate,0,{ActionTimeOwnerPhase::awaiting_process_choice,ActionTimeOwnerPhase::awaiting_output_space,ActionTimeOwnerPhase::awaiting_settlement}};}
