  header(x.materials.common,j.terms.acceptance_ref);terms_shape(x,j.terms);take(x.original.validate_craft_terms(j.terms,&j.terms.acceptance_ref));if(take(compare_world_moments(j.terms.accepted_at,at))>0)fail("FutureCraftJob",j.id);participant_qualification(x,j.terms,&j.terms.acceptance_ref);
  distinct(j.actual_service_refs,j.id);distinct(j.stage_result_refs,j.id);distinct(j.gate_result_refs,j.id);distinct(j.facility_claim_refs,j.id);distinct(j.pace_change_refs,j.id);distinct(j.control_refs,j.id);if(j.facility_claim_refs.empty())fail("CraftFacilityClaimRequired",j.id);
  take(validate_craft_material_history(x.materials,j));const auto*work=take(read_craft_actual_work(x,j));const auto*gate=std::get_if<CraftWorkGate>(&work->gate);if(!gate||!same_work_binding(gate->execution_binding,j.execution_binding))fail("CraftSharedWorkBindingMismatch",j.id);
  const auto owner=take(action_sources.read_action_time_owner(craft_action_time_registration(),j.execution_binding.action_id));take(action_sources.validate_shared_action_sources(craft_action_time_registration(),owner,*work));
  const auto chronology=take(read_craft_service_chronology(x,j));if(!same(chronology.gate_opened_at,gate->gate_opened_at)||!same(chronology.last_accounted_at,gate->last_accounted_at)||chronology.gate_ordinal!=gate->gate_ordinal||chronology.phase!=work->execution.phase||take(compare_fractions(chronology.earned_service_units.value,gate->earned_service_units.value,x.arithmetic_budget))!=0)fail("CraftElapsedServiceCoverageMismatch",j.id);
  for(const auto&id:j.gate_result_refs){const auto*g=take(read_craft_actual_gate(x,id));if(take(compare_world_moments(g->occurred_at,at))>0)fail("FutureCraftGate",id);}
