  if((j.phase==CraftJobPhase::completed)!=j.completion_fact_id.has_value())fail("CraftCompletionPhaseMismatch",j.id);
  if(j.completion_fact_id){const auto*result=x.materials.jobs.completions.find(*j.completion_fact_id);if(!result||result->id!=*j.completion_fact_id||result->job_id!=j.id||!j.quality_result_ref||result->quality_result_ref!=*j.quality_result_ref||result->output.original_lot_id.empty()||result->destination_inventory_id!=j.terms.output_inventory_id||take(compare_world_moments(result->occurred_at,at))>0)fail("CraftCompletionSourceRequired",j.id);header(x.materials.common,craft_completion_source(result->id));before(x.materials.common,result->quality_result_ref,result->id);take(x.original.validate_actual_craft_completion(j,*result));}
